"use client";

import { useEffect, useState } from "react";

type MicMode = "push" | "open" | "wake";

const OPTIONS: { value: MicMode; label: string }[] = [
  { value: "push", label: "Press Listen" },
  { value: "open", label: "Leave the microphone on" },
  { value: "wake", label: "Wake word: Fonia" },
];

export default function FoniaSettings() {
  const [mode, setMode] = useState<MicMode>("push");
  const [note, setNote] = useState("Microphone is off until you press Listen.");

  useEffect(() => {
    void fetch("/api/fonia/settings")
      .then((response) => response.json())
      .then((data: { micMode?: MicMode }) => {
        if (data.micMode === "open" || data.micMode === "wake" || data.micMode === "push") {
          setMode(data.micMode);
          setNote(noteFor(data.micMode));
        }
      })
      .catch(() => setNote("Microphone setting could not be read."));
  }, []);

  async function choose(next: MicMode) {
    setMode(next);
    setNote(noteFor(next));
    const response = await fetch("/api/fonia/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ micMode: next }),
    });
    if (!response.ok) setNote("The microphone setting was not saved.");
  }

  return (
    <div style={{ padding: "10px 12px", borderBottom: "1px solid var(--border)", flexShrink: 0 }}>
      <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: 6 }}>
        Microphone
      </div>
      <select
        aria-label="Microphone"
        value={mode}
        onChange={(event) => void choose(event.target.value as MicMode)}
        style={{ width: "100%", background: "var(--bg-input)", color: "var(--text-primary)", border: "1px solid var(--border)", borderRadius: 6, padding: "6px 8px", fontSize: 12 }}
      >
        {OPTIONS.map((option) => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </select>
      <p style={{ margin: "6px 0 0", fontSize: 11, color: "var(--text-muted)", lineHeight: 1.4 }}>{note}</p>
    </div>
  );
}

function noteFor(mode: MicMode): string {
  if (mode === "open") return "The microphone stays on and sends what it hears.";
  if (mode === "wake") return "Say Fonia, then say the request.";
  return "Microphone is off until you press Listen.";
}
